// @generated by:gauntlet run:godseye-local-hermes-chat
import { randomUUID } from "node:crypto";
import { DomainError } from "@godseye/core";
import { Hono } from "hono";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
  type ChatStreamOptions,
  registerAgentChatTransport,
} from "../apps/control-api/src/agent-chat-transport.js";
import type { ControlEnvironment } from "../apps/control-api/src/api-types.js";
import { chatFrames } from "./helpers/agents-chat-stream.js";
import { type AgentsFixture, agentsFixture } from "./helpers/agents-fixture.js";

// This layer uses the real journal/transport; authentication callback is a controlled boundary.
describe("bounded private Hermes chat transport", () => {
  let f: AgentsFixture;
  const bodies: ReadableStream<Uint8Array>[] = [];
  beforeEach(async () => {
    f = await agentsFixture();
  });
  afterEach(async () => {
    for (const body of bodies.splice(0)) if (!body.locked) await body.cancel();
    await f.store.close();
  });
  async function setup(options: ChatStreamOptions = {}) {
    const actor = f.freshOwner();
    let revoked = false;
    const app = new Hono<ControlEnvironment>();
    app.use("*", async (c, next) => {
      c.set("actor", actor);
      await next();
    });
    app.onError((error, c) =>
      error instanceof DomainError
        ? c.json({ error: { code: error.code } }, error.status as 400)
        : c.json({ error: { code: "INVALID_INPUT" } }, 422),
    );
    registerAgentChatTransport(
      app,
      f.infrastructure.agents,
      async () => {
        if (revoked) throw new Error("Controlled owner revocation");
        return actor;
      },
      {
        lifetimeMs: 3000,
        pollMs: 5,
        reauthenticateMs: 10,
        idleConsumerMs: 1000,
        heartbeatMs: 2000,
        ...options,
      },
    );
    const profile = await f.create();
    const detail = await f.infrastructure.agents.chatCreate(
      actor,
      {
        profileId: profile.id,
        expectedRevision: profile.revision,
        title: "Transport fixture",
      },
      randomUUID(),
    );
    const id = detail.conversation.id;
    async function open(query = "", signal?: AbortSignal) {
      const response = await app.request(
        `http://fixture.invalid/api/v1/agents/conversations/${id}/events${query}`,
        { signal },
      );
      if (response.body) bodies.push(response.body);
      return response;
    }
    return {
      app,
      id,
      actor,
      open,
      revoke: () => {
        revoked = true;
      },
      detail,
    };
  }

  it("T-AC-745 bounds per-conversation connections and immediately releases an aborted unread stream", async () => {
    const s = await setup({ maxConnections: 1, perConversation: 1 });
    const abort = new AbortController(),
      first = await s.open("", abort.signal);
    expect(first.status).toBe(200);
    expect((await s.open()).status).toBe(429);
    abort.abort();
    expect((await s.open()).status).toBe(200);
    expect(f.provider.submissions).toHaveLength(0);
  });

  it("T-AC-745 expires a non-reading stream and releases finite capacity", async () => {
    const s = await setup({ maxConnections: 1, perConversation: 1, lifetimeMs: 80 });
    expect((await s.open()).status).toBe(200);
    expect((await s.open()).status).toBe(429);
    await new Promise((done) => setTimeout(done, 120));
    expect((await s.open()).status).toBe(200);
  });

  it("T-AC-745 closes a waiting reader when its owner authority is revoked", async () => {
    const s = await setup();
    const response = await s.open();
    if (!response.body) throw new Error("Expected actual SSE body");
    const stream = chatFrames(response.body);
    expect((await stream.next())?.event).toBe("ready");
    s.revoke();
    expect(await stream.next()).toBeNull();
    await stream.reader.cancel();
    expect(f.provider.stops).toHaveLength(0);
  });

  it("T-AC-751 refuses malformed cursor and authority query fields before successful headers", async () => {
    const s = await setup();
    for (const query of [
      "?after=-1",
      "?after=01",
      "?after=1.5",
      "?after=NaN",
      "?after=9007199254740992",
      "?after=0&after=1",
      "?profileId=foreign",
    ]) {
      expect((await s.open(query)).status).toBe(422);
    }
    expect(f.provider.submissions).toHaveLength(0);
  });

  it("T-AC-744 replays only events after the durable cursor without resubmitting work", async () => {
    const s = await setup();
    await f.infrastructure.agents.chatSend(
      s.actor,
      s.id,
      {
        input: "One reconnectable request",
        expectedRevision: s.detail.conversation.revision,
      },
      randomUUID(),
    );
    await f.work();
    const expected = await f.infrastructure.agents.chatEvents(s.actor, s.id, 0);
    const first = expected.events[0];
    if (!first) throw new Error("Expected a durable turn event");
    const response = await s.open(`?after=${first.cursor}`);
    if (!response.body) throw new Error("Expected resumed SSE body");
    const stream = chatFrames(response.body);
    expect((await stream.next())?.event).toBe("ready");
    for (const event of expected.events.slice(1)) {
      const frame = await stream.next();
      expect(frame).toMatchObject({ event: "chat", id: String(event.cursor), data: event });
    }
    await stream.reader.cancel();
    expect(f.provider.submissions).toHaveLength(1);
  });
});
